@startuml

class Subscription {
  + type : string
}

class Customer {
  + name : string
  + surname : string
  + age : int
  + address : string
  + profession : string
}

class WorkoutPlan {
  + frequency : int
}

class Exercise {
  + name : string
  + repetitions : int
}

class Service {
  + name : string
}

class MedicalCheck {
  + weight : float
  + bodyFat : float
  + electrocardiogram : string
  + restingHeartbeat : int
  + stressHeartbeat : int
}

class MedicalStaff {
  + name : string
}

class Diet {
  + description : string
}

class FitnessLevel {
  + level : string
}

class Gym {
  + computeMonthlyBalance() : double
  + computeYearlyBalance() : double
  + sendArrearsReminder()
  + sendMedicalCheckReminder()
}

Customer "1" -- "1" Subscription
Customer "1" -- "0..1" WorkoutPlan
Customer "1" -- "0..*" Service
Customer "0..1" -- "0..*" MedicalCheck
Customer "0..1" -- "0..1" Diet
Customer "0..1" -- "0..1" FitnessLevel
MedicalStaff "1" -- "*" MedicalCheck
MedicalStaff "1" -- "*" Diet
MedicalStaff "1" -- "*" FitnessLevel
WorkoutPlan "1" -- "*" Exercise
Gym "1" -- "*" Customer
Gym "1" -- "*" Subscription

@enduml

